import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

// Only synthetic credentials generated by the parent test. This disk adapter
// deliberately does not claim native SecureStore encryption or device behavior.
function mockSecureRead(): Record<string, string> {
  const filename = resolve(process.env.EVRY_RESTART_DIRECTORY!, 'synthetic-keychain.json');
  return existsSync(filename) ? JSON.parse(readFileSync(filename, 'utf8')) : {};
}
function mockSecureWrite(values: Record<string, string>) {
  writeFileSync(resolve(process.env.EVRY_RESTART_DIRECTORY!, 'synthetic-keychain.json'), JSON.stringify(values));
}
jest.mock('expo-secure-store', () => ({
  WHEN_UNLOCKED_THIS_DEVICE_ONLY: 'device',
  getItemAsync: async (key: string) => mockSecureRead()[key] ?? null,
  setItemAsync: async (key: string, value: string) => { mockSecureWrite({ ...mockSecureRead(), [key]: value }); },
  deleteItemAsync: async (key: string) => { const values = mockSecureRead(); delete values[key]; mockSecureWrite(values); },
}));
jest.mock('expo-sqlite', () => jest.requireActual('../testing/sqlite-native').createSQLiteBridge(process.env.EVRY_RESTART_DIRECTORY));
jest.mock('expo-crypto', () => ({
  CryptoDigestAlgorithm: { SHA256: 'sha256' },
  digestStringAsync: async (_algorithm: string, value: string) => jest.requireActual('node:crypto').createHash('sha256').update(value).digest('hex'),
  randomUUID: () => jest.requireActual('node:crypto').randomUUID(),
}));
let mockOnline = false;
jest.mock('@react-native-community/netinfo', () => ({ __esModule: true, default: {
  fetch: async () => ({ isConnected: mockOnline, isInternetReachable: mockOnline }),
} }));

it(`executes ${process.env.EVRY_RESTART_PHASE} using disk state from previous terminated processes`, async () => {
  const transport = jest.requireActual('node-fetch');
  global.Request = transport.Request;
  global.Response = transport.Response;
  global.Headers = transport.Headers;
  global.fetch = async (input, init) => {
    if (!mockOnline) throw new TypeError('Synthetic offline');
    return transport(input, init);
  };
  // openapi-fetch captures Request/fetch when a client is constructed. Install
  // one coherent native transport before loading the real API/session modules.
  const api = jest.requireActual<typeof import('../api/client')>('../api/client');
  const db = jest.requireActual<typeof import('../db/database')>('../db/database');
  const { useSessionStore } = jest.requireActual<typeof import('../auth/session-store')>('../auth/session-store');
  const { useTrainingStore } = jest.requireActual<typeof import('../training/training-store')>('../training/training-store');
  const { syncPendingWorkouts } = jest.requireActual<typeof import('./sync-engine')>('./sync-engine');
  const phase = process.env.EVRY_RESTART_PHASE;
  const userId = process.env.EVRY_RESTART_USER!;
  const exerciseId = process.env.EVRY_RESTART_EXERCISE!;
  if (phase === 'create-offline') {
    mockOnline = true;
    await useSessionStore.getState().login(process.env.EVRY_RESTART_EMAIL!, process.env.EVRY_RESTART_PASSWORD!);
    expect(useSessionStore.getState().error).toBeNull();
    expect(useSessionStore.getState()).toMatchObject({ status: 'authenticated', user: { id: userId } });
    mockOnline = false;
  } else {
    // initialize restores persisted identity before attempting the network;
    // no successful GET or login can fabricate offline recovery in this phase.
    await useSessionStore.getState().initialize();
    expect(useSessionStore.getState()).toMatchObject({ status: 'authenticated', offline: true, user: { id: userId } });
  }
  const owner = api.captureMobileSession();
  await useTrainingStore.getState().initialize(owner);
  expect(useTrainingStore.getState().ready).toBe(true);
  if (phase === 'create-offline') {
    await useTrainingStore.getState().startWorkout('Durable offline restart');
    await useTrainingStore.getState().addSet(exerciseId);
    const setId = useTrainingStore.getState().activeWorkout!.sets[0].clientId;
    await useTrainingStore.getState().updateSet(setId, { weightKg: 55, reps: 8 });
    await syncPendingWorkouts(owner);
    expect(await db.pendingSyncRows(owner)).toHaveLength(1);
  } else if (phase === 'finish-offline') {
    const workout = useTrainingStore.getState().activeWorkout;
    expect(workout).toMatchObject({ name: 'Durable offline restart', status: 'ACTIVE', sets: [{ exerciseId, weightKg: 55, reps: 8 }] });
    await useTrainingStore.getState().updateSet(workout!.sets[0].clientId, { reps: 9 });
    await useTrainingStore.getState().finishWorkout();
    await syncPendingWorkouts(owner);
    expect(await db.loadActiveWorkout(owner)).toBeNull();
    expect(JSON.parse((await db.pendingSyncRows(owner))[0].payload)).toMatchObject({ status: 'COMPLETED', sets: [{ reps: 9 }] });
  } else if (phase === 'sync-online') {
    expect(await db.loadActiveWorkout(owner)).toBeNull();
    expect(await db.pendingSyncRows(owner)).toHaveLength(1);
    const oldRefresh = mockSecureRead()['evry.mobile.refresh-token'];
    mockOnline = true;
    await syncPendingWorkouts(owner);
    expect(await db.pendingSyncRows(owner)).toEqual([]);
    expect(await db.currentSyncState(owner)).toBe('synced');
    expect(mockSecureRead()['evry.mobile.refresh-token']).not.toBe(oldRefresh);
  } else { throw new Error('Unknown restart phase.'); }
});
